INSERT INTO public.templates (id, title, slug, tagline, description, cover_image, category, suggested_duration_days, difficulty, featured)
VALUES
  ('11111111-1111-1111-1111-111111111001', '7-Day Soft Reset', '7-day-soft-reset', 'A gentle pause to declutter your mind, space, and routine.', 'Ideal for overcoming burnout or preparing for a new season. Ease into intentional habits with low stress and high nourishment.', 'https://images.unsplash.com/photo-1544717305-2782549b5136?q=80&w=1000&auto=format&fit=crop', 'Self-Care', 7, 'Gentle', true),
  ('11111111-1111-1111-1111-111111111002', '7-Day Confidence Boost', '7-day-confidence-boost', 'Elevate your self-esteem, posture, and internal voice.', 'Short actionable daily missions to rewire your mindset, express yourself boldly, and step into self-assurance.', 'https://images.unsplash.com/photo-1506126613408-eca07ce68773?q=80&w=1000&auto=format&fit=crop', 'Mindset', 7, 'Beginner', false),
  ('11111111-1111-1111-1111-111111111003', '7-Day Healthy Glow', '7-day-healthy-glow', 'Hydration, nourishing meals, and restorative movement.', 'Kickstart radiant energy and luminous skin through consistent sleep, water intake, clean fueling, and facial self-care.', 'https://images.unsplash.com/photo-1512290900672-1f5be1c6bf4c?q=80&w=1000&auto=format&fit=crop', 'Wellness', 7, 'Gentle', true),
  ('11111111-1111-1111-1111-111111111004', '14-Day Digital Detox', '14-day-digital-detox', 'Reclaim your focus, dopamine levels, and peace of mind.', 'Gradually reduce screen time, replace doom-scrolling with reading and nature, and rebuild a healthy relationship with technology.', 'https://images.unsplash.com/photo-1518241353330-0f7941c2d9b5?q=80&w=1000&auto=format&fit=crop', 'Productivity', 14, 'Moderate', false),
  ('11111111-1111-1111-1111-111111111005', '21-Day Consistency Challenge', '21-day-consistency-challenge', 'Anchor 3 foundational habits into your daily autopilot.', 'Neuroscience shows small repetitive actions build lasting automatic neural pathways. Focus on flawless execution over intensity.', 'https://images.unsplash.com/photo-1499209974431-9dddcece7f88?q=80&w=1000&auto=format&fit=crop', 'Habits', 21, 'Moderate', true),
  ('11111111-1111-1111-1111-111111111006', '30-Day Glow-Up Challenge', '30-day-glow-up-challenge', 'The quintessential physical, mental, and lifestyle transformation.', 'Harmonious holistic upgrade spanning skincare, wardrobe curation, physical movement, healthy eating, mindset, and organization.', 'https://images.unsplash.com/photo-1515377905703-c4788e51af15?q=80&w=1000&auto=format&fit=crop', 'Holistic', 30, 'Moderate', true),
  ('11111111-1111-1111-1111-111111111007', '30-Day Academic Comeback', '30-day-academic-comeback', 'Elevate your GPA, study systems, and intellectual mastery.', 'Deep work sprints, active recall, structured note-taking, and intentional scheduling to turn your academic trajectory around.', 'https://images.unsplash.com/photo-1434030216411-0b793f4b4173?q=80&w=1000&auto=format&fit=crop', 'Academic', 30, 'Intensive', true),
  ('11111111-1111-1111-1111-111111111008', '30-Day Productivity Reset', '30-day-productivity-reset', 'Organize your digital workspace, master time-blocking, and execute.', 'Replace reactive busywork with high-impact deep focus. Clean inboxes, streamline workflows, and finish pending projects.', 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?q=80&w=1000&auto=format&fit=crop', 'Productivity', 30, 'Moderate', false),
  ('11111111-1111-1111-1111-111111111009', '30-Day Mindful Living', '30-day-mindful-living', 'Ground yourself in the present moment with daily reflection and peace.', 'Cultivate calmness, breathwork, gratitude journaling, somatic awareness, and emotional regulation.', 'https://images.unsplash.com/photo-1506126613408-eca07ce68773?q=80&w=1000&auto=format&fit=crop', 'Mindset', 30, 'Gentle', false),
  ('11111111-1111-1111-1111-111111111010', '45-Day Self-Improvement', '45-day-self-improvement', 'Mid-length transformational sprint across body, finances, and mind.', 'Structured across 3 distinct 15-day phases: Foundation, Acceleration, and Integration.', 'https://images.unsplash.com/photo-1494774157365-9e04c6720e47?q=80&w=1000&auto=format&fit=crop', 'Holistic', 45, 'Challenging', false),
  ('11111111-1111-1111-1111-111111111011', '60-Day Wellness Challenge', '60-day-wellness-challenge', 'Deep physiological renewal, stamina development, and vitality.', 'Targeted nutrition, daily steps, strength conditioning, and restorative sleep architecture for sustainable health.', 'https://images.unsplash.com/photo-1518611012118-696072aa579a?q=80&w=1000&auto=format&fit=crop', 'Wellness', 60, 'Challenging', false),
  ('11111111-1111-1111-1111-111111111012', '75-Day Discipline Challenge', '75-day-discipline-challenge', 'Uncompromising mental resilience, physical toughness, and grit.', 'Two workouts daily, structured clean eating, gallon of water, 10 pages of non-fiction, and zero excuses.', 'https://images.unsplash.com/photo-1517838277536-f5f99be501cd?q=80&w=1000&auto=format&fit=crop', 'Discipline', 75, 'Intense', true),
  ('11111111-1111-1111-1111-111111111013', '90-Day Personal Growth', '90-day-personal-growth', 'A complete life quarter designed for total self-actualization.', 'Three 30-day blocks encompassing identity shifts, skill mastery, career or creative execution, and enduring lifestyle polish.', 'https://images.unsplash.com/photo-1522202176988-66273c2fd55f?q=80&w=1000&auto=format&fit=crop', 'Holistic', 90, 'Intense', false)
